const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const gerdReservoir = ee.Geometry.Point([35.093, 11.232]); // Approximate center of GERD reservoir

  const startDate_sep = '2021-09-01';
  const endDate_sep = '2021-09-30';
  const startDate_feb = '2022-02-01';
  const endDate_feb = '2022-02-28';

  // 2. Data Acquisition & Check
  const sral_collection = ee.ImageCollection('COPERNICUS/SRAL/S3_OL_2_WAT__WAVE')
    .filterBounds(gerdReservoir)
    .filter(ee.Filter.eq('qcc_flag', 0)); // Filter for good quality measurements

  const col_sep = sral_collection.filterDate(startDate_sep, endDate_sep);
  const col_feb = sral_collection.filterDate(startDate_feb, endDate_feb);

  const size_sep = await col_sep.size().getInfo();
  const size_feb = await col_feb.size().getInfo();

  if (size_sep === 0 || size_feb === 0) {
    console.log(`2021 Sep Images: ${size_sep}, 2022 Feb Images: ${size_feb}`);
    console.log("C1"); // Empty Collection
    return;
  }

  // 3. Processing & 4. Calculation
  // Calculate mean water level for each period
  const mean_level_sep_result = await col_sep
    .select('water_level_m')
    .reduceColumns(ee.Reducer.mean(), ['water_level_m'])
    .get('mean')
    .getInfo();

  const mean_level_feb_result = await col_feb
    .select('water_level_m')
    .reduceColumns(ee.Reducer.mean(), ['water_level_m'])
    .get('mean')
    .getInfo();

  // 5. Validation & Final Answer
  if (mean_level_sep_result === null || mean_level_feb_result === null ||
      isNaN(mean_level_sep_result) || isNaN(mean_level_feb_result)) {
    console.log(`2021 Sep Mean: ${mean_level_sep_result}, 2022 Feb Mean: ${mean_level_feb_result}`);
    console.log("C3"); // Calculation Failure (NaN or Null)
    return;
  }

  console.log(`2021 Sep Obs: ${size_sep}, Mean Water Level: ${mean_level_sep_result.toFixed(2)} m`);
  console.log(`2022 Feb Obs: ${size_feb}, Mean Water Level: ${mean_level_feb_result.toFixed(2)} m`);

  if (mean_level_feb_result < mean_level_sep_result) {
    console.log("A"); // Yes, water level decreased
  } else {
    console.log("B"); // No, water level did not decrease or increased
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
